var countLabelsInRecipes = (recipes2) => {
  const labelCounts = {};
  Object.values(recipes2).forEach((recipe) => {
    if (recipe.labels && recipe.labels.length) {
      recipe.labels.forEach((label) => {
        if (!(label in labelCounts)) {
          labelCounts[label] = 1;
        } else {
          labelCounts[label]++;
        }
      });
    }
  });
  const result = Object.keys(labelCounts).map((label) => ({
    label,
    count: labelCounts[label]
  }));
  return result;
};

